  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\n// ============================================\n// MODELS\n// ============================================\n\n// User Model \nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  password       String\n  name           String\n  rollNumber     String?  @unique\n  role           String   @default(\"STUDENT\") // \"STUDENT\" or \"ADMIN\"\n  profilePicture String?\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  feedbacks     Feedback[]\n  votes         PollVote[]\n  notifications Notification[]\n  suggestions   Suggestion[]\n  systemLogs    SystemLog[]\n\n  @@map(\"users\")\n}\n\n// Meal Plan \nmodel MealPlan {\n  id          String   @id @default(cuid())\n  day         String // \"MONDAY\", \"TUESDAY\", etc.\n  mealType    String // \"BREAKFAST\", \"LUNCH\", \"DINNER\"\n  name        String\n  description String?\n  price       Float?\n  isActive    Boolean  @default(true)\n  createdBy   String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  specialMeals SpecialMeal[]\n  feedbacks    Feedback[]\n\n  @@unique([day, mealType])\n  @@map(\"meal_plans\")\n}\n\n// Special Meal\nmodel SpecialMeal {\n  id          String   @id @default(cuid())\n  title       String\n  description String?\n  date        DateTime @unique\n  mealType    String // \"REGULAR\", \"SPECIAL_MONDAY\", \"SPECIAL_THURSDAY\"\n  isActive    Boolean  @default(true)\n  createdBy   String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  mealPlanId String?\n  mealPlan   MealPlan? @relation(fields: [mealPlanId], references: [id])\n  polls      Poll[]\n\n  @@map(\"special_meals\")\n}\n\n// Poll\nmodel Poll {\n  id            String   @id @default(cuid())\n  question      String\n  description   String?\n  startDate     DateTime @default(now())\n  endDate       DateTime\n  status        String   @default(\"DRAFT\") // \"DRAFT\", \"ACTIVE\", \"CLOSED\"\n  isActive      Boolean  @default(true)\n  pollType      String // \"DIET_PREFERENCE\", \"MEAT_SELECTION\"\n  specialMealId String\n  createdBy     String\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  specialMeal SpecialMeal  @relation(fields: [specialMealId], references: [id], onDelete: Cascade)\n  options     PollOption[]\n  votes       PollVote[]\n\n  @@map(\"polls\")\n}\n\n// Poll Option\nmodel PollOption {\n  id     String     @id @default(cuid())\n  text   String\n  value  String\n  pollId String\n  poll   Poll       @relation(fields: [pollId], references: [id], onDelete: Cascade)\n  votes  PollVote[]\n\n  @@unique([pollId, value])\n  @@map(\"poll_options\")\n}\n\n// Poll Vote\nmodel PollVote {\n  id       String   @id @default(cuid())\n  userId   String\n  pollId   String\n  optionId String\n  votedAt  DateTime @default(now())\n\n  user   User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  poll   Poll       @relation(fields: [pollId], references: [id], onDelete: Cascade)\n  option PollOption @relation(fields: [optionId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, pollId])\n  @@map(\"poll_votes\")\n}\n\n// Feedback\nmodel Feedback {\n  id           String    @id @default(cuid())\n  userId       String\n  rating       Int\n  comment      String\n  mealPlanId   String?\n  status       String    @default(\"PENDING\") // \"APPROVED\", \"PENDING\", \"FLAGGED\", \"REJECTED\"\n  flaggedWords String\n  reviewedBy   String?\n  reviewedAt   DateTime?\n  adminNote    String?\n  isAnonymous  Boolean   @default(false)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  mealPlan MealPlan? @relation(fields: [mealPlanId], references: [id])\n\n  @@index([status])\n  @@index([userId])\n  @@map(\"feedbacks\")\n}\n\n// Suggestion\nmodel Suggestion {\n  id            String    @id @default(cuid())\n  userId        String\n  title         String\n  description   String\n  status        String    @default(\"PENDING\") // \"APPROVED\", \"PENDING\", \"FLAGGED\", \"REJECTED\"\n  flaggedWords  String\n  reviewedBy    String?\n  reviewedAt    DateTime?\n  adminResponse String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([status])\n  @@index([userId])\n  @@map(\"suggestions\")\n}\n\n// Grocery Bill\nmodel GroceryBill {\n  id          String   @id @default(cuid())\n  receiptUrl  String\n  receiptName String\n  totalAmount Float\n  billDate    DateTime\n  uploadedBy  String\n  description String?\n  mealCycle   String?\n  fileSize    Int?\n  fileType    String?\n  items       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([billDate])\n  @@map(\"grocery_bills\")\n}\n\n// Cost Summary\nmodel CostSummary {\n  id              String   @id @default(cuid())\n  cycleName       String   @unique\n  startDate       DateTime\n  endDate         DateTime\n  totalCost       Float\n  averageMealCost Float?\n  totalMeals      Int?\n  notes           String?\n  generatedBy     String\n  generatedAt     DateTime @default(now())\n\n  @@map(\"cost_summaries\")\n}\n\n// Notification\nmodel Notification {\n  id          String    @id @default(cuid())\n  userId      String\n  title       String\n  message     String\n  type        String // \"MEAL_TIME_CHANGE\", \"SPECIAL_MEAL_UPDATE\", etc.\n  status      String    @default(\"UNREAD\") // \"READ\", \"UNREAD\"\n  metadata    String?\n  createdAt   DateTime  @default(now())\n  deliveredAt DateTime?\n  readAt      DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, status])\n  @@index([createdAt])\n  @@map(\"notifications\")\n}\n\n// Meal Time Setting\nmodel MealTimeSetting {\n  id          String   @id @default(cuid())\n  mealType    String   @unique // \"BREAKFAST\", \"LUNCH\", \"DINNER\"\n  time        String\n  bufferTime  Int?\n  description String?\n  updatedBy   String\n  updatedAt   DateTime @updatedAt\n  createdAt   DateTime @default(now())\n\n  @@map(\"meal_time_settings\")\n}\n\n// System Log\nmodel SystemLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  action    String\n  details   String?\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"system_logs\")\n}\n",
